function titles(html) {
  return [...html.matchAll(/class="task-title">(.*?)<\/span>/g)].map((match) => match[1]);
}

function assertSelection(html, selection) {
  for (const [name, value] of Object.entries(selection)) {
    if (name === 'filter' || name === 'priorityFilter') {
      const id = name === 'filter' ? 'task-filter' : 'priority-filter';
      const select = html.match(new RegExp(`<select id="${id}"[^>]*>([\\s\\S]*?)</select>`))[1];
      assert.ok(select.includes(`<option selected>${value}</option>`));
    }
    for (const [, form] of html.matchAll(/<form[^>]*method="post">([\s\S]*?)<\/form>/g)) {
      assert.ok(form.includes(`name="${name}" value="${value}"`));
    }
  }
  const filterForm = html.match(/<form class="task-filter"[^>]*>([\s\S]*?)<\/form>/)[1];
  for (const name of ['dueFrom', 'dueThrough']) {
    assert.ok(filterForm.includes(`name="${name}" value="${selection[name]}"`));
  }
}

test('due range validation shares calendar rules and validates ordering after trimming', () => {
  assert.deepEqual(normalizeDueRange(' \t ', ''), { dueFrom: '', dueThrough: '' });
  assert.deepEqual(normalizeDueRange(' 0001-01-01 ', ' 9999-12-31 '), {
    dueFrom: '0001-01-01', dueThrough: '9999-12-31',
  });
  assert.deepEqual(normalizeDueRange('2000-02-29', '2000-02-29'), {
    dueFrom: '2000-02-29', dueThrough: '2000-02-29',
  });
  for (const invalid of ['0000-01-01', '10000-01-01', '1900-02-29', '2024-04-31', '2024-2-01', '<invalid>']) {
    for (const pair of [[invalid, ''], ['', invalid]]) {
      assert.equal(normalizeDueRange(...pair).error, 'Due range must use valid YYYY-MM-DD dates');
    }
  }
  assert.equal(normalizeDueRange('2024-03-01', '2024-02-29').error,
    'Due from must not be after Due through');
});

test('inclusive due ranges intersect filters and preserve data through edits, validation, archive and restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-ranges-'));
  let running;
  try {
    const databasePath = join(directory, 'workboard.sqlite');
    running = await launch(databasePath);
    const get = async (path) => (await fetch(`${running.baseUrl}${path}`)).text();
    const post = (path, values = {}) => fetch(`${running.baseUrl}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    const apply = (selection, rangeFrom, rangeThrough) => fetch(`${running.baseUrl}/projects/1?${
      new URLSearchParams({ ...selection, applyDueRange: '1', rangeFrom, rangeThrough })
    }`, { redirect: 'manual' });
    await post('/projects', { name: 'First' });
    await post('/projects', { name: 'Other' });
    const tasks = [];
    for (const [index, date] of ['', '0001-01-01', '2024-02-28', '2024-02-29', '2024-03-01', '9999-12-31'].entries()) {
      const id = index + 1;
      const title = `Task ${id}`;
      const priority = ['High', 'Low', 'Normal'][index % 3];
      const completed = index % 2 === 1;
      await post('/projects/1/tasks', { title });
      await post(`/projects/1/tasks/${id}/due-date`, { dueDate: date });
      await post(`/projects/1/tasks/${id}/priority`, { priority });
      if (completed) await post(`/projects/1/tasks/${id}/completion`, { completed: 'on' });
      tasks.push({ title, date, priority, completed });
    }
    await post('/projects/2/tasks', { title: 'Other task' });
    const summary = await get('/');
    const other = await get('/projects/2');
    const original = await get('/projects/1');
    assert.match(original, /<label for="due-from">Due from<\/label>/);
    assert.match(original, /<label for="due-through">Due through<\/label>/);
    assert.match(original, /id="due-from" name="rangeFrom" type="text" value=""/);
    assert.match(original, /id="due-through" name="rangeThrough" type="text" value=""/);
    assert.match(original, />Apply due range<\/button>/);
    const ranges = [['', ''], ['2024-02-29', ''], ['', '2024-02-29'],
      ['2024-02-28', '2024-03-01'], ['2024-02-29', '2024-02-29'], ['0001-01-01', '9999-12-31']];
    for (const [dueFrom, dueThrough] of ranges) {
      for (const filter of ['All', 'Open', 'Completed']) {
        for (const priorityFilter of ['All', 'Low', 'Normal', 'High']) {
          const selection = { filter, priorityFilter, dueFrom, dueThrough };
          const response = await apply(selection, ` ${dueFrom} `, ` ${dueThrough} `);
          assert.equal(response.status, 303);
          const html = await get(response.headers.get('location'));
          assertSelection(html, selection);
          assert.deepEqual(titles(html), tasks.filter((task) =>
            (filter === 'All' || task.completed === (filter === 'Completed')) &&
            (priorityFilter === 'All' || task.priority === priorityFilter) &&
            (!(dueFrom || dueThrough) || (task.date &&
              (!dueFrom || task.date >= dueFrom) && (!dueThrough || task.date <= dueThrough))))
            .map((task) => task.title));
        }
      }
    }
    assert.equal(await get('/'), summary);
    assert.equal(await get('/projects/1'), original);
    const selection = { filter: 'Completed', priorityFilter: 'High', dueFrom: '2024-02-29', dueThrough: '2024-03-01' };
    const path = `/projects/1?${new URLSearchParams(selection)}`;
    assert.deepEqual(titles(await get(path)), ['Task 4']);
    for (const [from, through, message] of [
      ['1900-02-29', '', 'Due range must use valid YYYY-MM-DD dates'],
      ['', '2024-04-31', 'Due range must use valid YYYY-MM-DD dates'],
      ['2024-03-01', '2024-02-29', 'Due from must not be after Due through'],
    ]) {
      const response = await apply(selection, from, through);
      assert.equal(response.status, 400);
      const html = await response.text();
      assert.ok(html.includes(`role="alert">${message}`));
      assertSelection(html, selection);
      assert.deepEqual(titles(html), ['Task 4']);
    }
    const edit = async (action, values, expectedTitles) => {
      const response = await post(action, { ...selection, ...values });
      assert.equal(response.status, 303);
      assert.equal(response.headers.get('location'), path);
      const html = await get(path);
      assertSelection(html, selection);
      assert.deepEqual(titles(html), expectedTitles);
      return html;
    };
    for (const [action, values] of [
      ['/projects/1/rename', { name: ' ' }],
      ['/projects/1/tasks', { title: ' ' }],
      ['/projects/1/tasks/4/rename', { title: ' ' }],
      ['/projects/1/tasks/4/due-date', { dueDate: '2024-02-30' }],
    ]) {
      const response = await post(action, { ...selection, ...values });
      assert.equal(response.status, 400);
      const html = await response.text();
      assertSelection(html, selection);
      assert.deepEqual(titles(html), ['Task 4']);
    }
    await edit('/projects/1/tasks/4/rename', { title: 'Renamed' }, ['Renamed']);
    await edit('/projects/1/rename', { name: 'Renamed project' }, ['Renamed']);
    await edit('/projects/1/default-task-priority', { priority: 'High' }, ['Renamed']);
    await edit('/projects/1/tasks', { title: 'New undated' }, ['Renamed']);
    await edit('/projects/1/tasks/4/due-date', { dueDate: '' }, []);
    await edit('/projects/1/tasks/4/due-date', { dueDate: '2024-03-01' }, ['Renamed']);
    await edit('/projects/1/tasks/4/priority', { priority: 'Low' }, []);
    await edit('/projects/1/tasks/4/priority', { priority: 'High' }, ['Renamed']);
    await edit('/projects/1/tasks/4/completion', {}, []);
    await edit('/projects/1/tasks/4/completion', { completed: 'on' }, ['Renamed']);
    assert.match(await get('/'), /3\/7 completed/);
    assert.equal(await get('/projects/2'), other);
    const saved = await get('/projects/1');
    const filtered = await get(path);
    await post('/projects/1/archive');
    const response = await apply(selection, '2024-02-29', '2024-03-01');
    assert.equal(response.status, 303);
    const archived = await get(response.headers.get('location'));
    assertSelection(archived, selection);
    assert.deepEqual(titles(archived), ['Renamed']);
    const rangeForm = archived.match(/<form class="due-range-form"[^>]*>([\s\S]*?)<\/form>/)[1];
    assert.doesNotMatch(rangeForm, /disabled/);
    assert.match(archived, /name="dueDate"[^>]* disabled/);
    assert.equal((await post('/projects/1/tasks/4/due-date', { dueDate: '2024-02-29' })).status, 409);
    await running.stop();
    running = await launch(databasePath);
    assert.equal(await get(path), archived);
    await post('/projects/1/restore');
    assert.equal(await get(path), filtered);
    assert.equal(await get('/projects/1'), saved);
    assert.match(saved, /id="due-from" name="rangeFrom" type="text" value=""/);
    assert.match(saved, /id="due-through" name="rangeThrough" type="text" value=""/);
  } finally {
    await running?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});
# Workboard

Requires Node.js 22.22.1. There are no application dependencies to install.

```sh
npm start
```

The server binds to `0.0.0.0` at `PORT` (default `8080`). Set `DB_PATH` to the
SQLite file to use (default `data/workboard.sqlite`). Its parent directory is
created automatically. Keep this file to preserve projects, tasks, and completion
state, priorities, and archive status between restarts. Existing databases are migrated
automatically without changing project IDs or tasks.

```sh
PORT=8080 DB_PATH=data/workboard.sqlite npm start
npm test
```

`GET /health` returns HTTP 200 with `{"status":"ok"}`. Project creation and
navigation use ordinary browser forms. Names are trimmed before persistence;
blank names return a visible validation alert without creating a project.
Each project has its own tasks. Titles are trimmed and blank titles show a
validation alert. Checkboxes save completion immediately; the task filter shows
All (the default), Open, or Completed tasks in creation order. Direct project
URLs remain usable after reloads and restarts.

The project filter defaults to Active and also offers Archived. Archive project
moves a project to Archived; Restore project returns it to Active, retaining its
tasks and completion state. Archived project pages allow viewing and filtering
tasks but disable creation and completion changes. The server also rejects task
changes on archived projects. Each project row shows completed/total task counts
across all its tasks.

Active project pages offer New project name and Rename project. Renaming trims
the name and preserves the project URL, creation order, tasks, and completion
summary. Blank names show a validation alert without changing the saved name.
Archived projects disable renaming, and the server rejects rename requests until
the project is restored. Renamed project names persist between restarts.

Each task row offers New task title and Rename task. Renaming trims the title
and updates the completion checkbox label while preserving ownership, creation
order, completion, filter membership, and project counts. Blank titles show an
alert without changing the saved task. Archived projects disable task renaming;
the server rejects changes until restoration. Task titles persist between restarts.

Each task row has a Task priority selector with Low, Normal, and High options.
Existing tasks default to Normal when migrated. Changes save immediately and persist
between restarts, independently of completion and renaming. Archived projects
disable priority changes in the browser and on the server; restoration preserves
the saved priorities.

Project pages also offer Priority filter with All (the default), Low, Normal,
and High options. Tasks must match both Task filter and Priority filter and
remain in creation order. Changing either filter or editing a task preserves
both selected filters; edits immediately update the matching rows. Filters do
not change saved tasks or completion summaries and remain usable when archived.
Opening a project from the project list starts with both filters set to All.

Each project has a Default task priority selector with Low, Normal, and High
options, initially Normal. Changes save immediately and apply only to tasks
created afterward in that project. Existing tasks and both selected filters
remain unchanged. Defaults persist through reloads, restarts, renaming, archival,
and restoration. Archived projects display the saved default but disable changes;
the server also rejects edits until restoration.

Each task has an optional Task due date textbox and Save due date button. Blank
values clear the date. Nonempty values are trimmed and must be real Gregorian
calendar dates in YYYY-MM-DD format, with years 0001 through 9999. Dates are
stored as calendar-day strings without timezone conversion. Invalid dates show
an alert and keep the saved date. Dates persist across restarts and renaming;
saving them preserves both filters and all other task data. Existing tasks
start without dates. Archived projects disable date editing in the browser and
on the server; restoration preserves dates and enables editing.

Project pages have Due from and Due through textboxes and Apply due range.
Boundaries use the same Gregorian date validation as task dates, are trimmed,
and match inclusively. Either boundary can be blank; with both blank, undated
tasks also match. The applied range intersects completion and priority filters
without changing saved tasks or all-task summaries. Invalid ranges show an alert
and preserve the previously applied range. Edits retain all selected filters and
immediately update matching rows. Range controls remain usable when archived.
The applied range is carried in the page URL and forms, not stored in SQLite;
opening a project from the list starts with empty boundaries.
import { createWorkboardServer } from './src/app.js';

const port = Number(process.env.PORT ?? 8080);
if (!Number.isInteger(port) || port < 0 || port > 65535) {
  throw new Error('PORT must be an integer between 0 and 65535');
}

const server = createWorkboardServer(process.env.DB_PATH ?? 'data/workboard.sqlite');
server.listen(port, '0.0.0.0', () => {
  console.log(`Workboard listening on 0.0.0.0:${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close());
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <link rel="stylesheet" href="/styles.css">
  <script src="/app.js" defer></script>
</head>
<body><main>${content}</main></body>
</html>`;
}

